// Generated by PatchPlan: Artanis gains a permanent hero with co-op style deployment and revival.

const string gameA_artanisHeroUnitType = "GameAArtanisHero";
const string gameA_artanisBeaconUnitType = "GameAArtanisReviveBeacon";
const string gameA_artanisHeroCooldown = "GameA/ArtanisHeroRevive";
const fixed gameA_artanisFirstArrivalTime = 240.0;
const fixed gameA_artanisReviveTime = 60.0;

unit[16] gameA_artanisHero;
unit[16] gameA_artanisBeacon;
int[16] gameA_artanisHeroPhase;
trigger gameA_artanisHeroTickTrigger;
trigger gameA_artanisHeroDiedTrigger;

bool GameA_ArtanisHeroPlayerIsActive (int player) {
    return libCOOC_gf_ActiveCommanderForPlayer(player) == "ProtossArtanis";
}

point GameA_ArtanisHeroSpawnPoint (int player) {
    if (UnitIsValid(gameA_artanisBeacon[player])) {
        return UnitGetPosition(gameA_artanisBeacon[player]);
    }
    return UnitTypePlacementFromPoint(gameA_artanisHeroUnitType, player, PlayerStartLocation(player), 12.0);
}

void GameA_ArtanisHeroRemoveAmonMechanics (unit hero) {
    UnitBehaviorRemove(hero, "MutatorAmonArtanisResurgence", c_unitBehaviorCountAll);
    UnitBehaviorRemove(hero, "VoidShade", c_unitBehaviorCountAll);
}

void GameA_ArtanisHeroStartCooldown (int player, fixed duration) {
    libCOUI_gv_cU_HeroReviveTimer[1][player] = duration;
    libNtve_gf_PlayerRemoveCooldown(player, gameA_artanisHeroCooldown);
    PlayerAddCooldown(player, gameA_artanisHeroCooldown, duration);
}

void GameA_ArtanisBeaconCreate (int player, fixed duration) {
    point placement;

    placement = UnitTypePlacementFromPoint(gameA_artanisBeaconUnitType, player, PlayerStartLocation(player), 12.0);
    UnitCreate(1, gameA_artanisBeaconUnitType, c_unitCreateIgnorePlacement, player, placement, 315.0);
    gameA_artanisBeacon[player] = UnitLastCreated();

    UnitBehaviorRemove(gameA_artanisBeacon[player], "AlarakReviveDisable", c_unitBehaviorCountAll);
    UnitAbilityEnable(gameA_artanisBeacon[player], "AlarakRevive", false);
    UnitAbilityEnable(gameA_artanisBeacon[player], "AlarakKnockback", false);
    UnitAbilityEnable(gameA_artanisBeacon[player], "AlarakACDeadlyCharge", false);
    UnitAbilityEnable(gameA_artanisBeacon[player], "AlarakEmpower", false);
    ActorSend(libNtve_gf_MainActorofUnit(gameA_artanisBeacon[player]), "SetTintColor 255,210,64");

    UnitSetPropertyFixed(gameA_artanisBeacon[player], c_unitPropLife, 0.1);
    UnitSetPropertyFixed(gameA_artanisBeacon[player], c_unitPropLifeRegen, UnitGetPropertyFixed(gameA_artanisBeacon[player], c_unitPropLifeMax, c_unitPropCurrent) / duration);
    UnitSetState(gameA_artanisBeacon[player], c_unitStateTooltipable, true);
    libCOUI_gf_SetHeroPanelUnit(1, gameA_artanisBeacon[player], player);
}

void GameA_ArtanisBeaconRemove (int player) {
    if (UnitIsValid(gameA_artanisBeacon[player])) {
        UnitRemove(gameA_artanisBeacon[player]);
    }
    gameA_artanisBeacon[player] = null;
}

void GameA_ArtanisHeroCreateWaiting (int player) {
    UnitCreate(1, gameA_artanisHeroUnitType, c_unitCreateIgnorePlacement, player, PlayerStartLocation(player), 270.0);
    gameA_artanisHero[player] = UnitLastCreated();
    GameA_ArtanisHeroRemoveAmonMechanics(gameA_artanisHero[player]);

    gameA_artanisHeroPhase[player] = 1;
    GameA_ArtanisHeroStartCooldown(player, gameA_artanisFirstArrivalTime);
    UnitSetPosition(gameA_artanisHero[player], Point(0.0, 0.0), false);
    UnitKill(gameA_artanisHero[player]);
    GameA_ArtanisBeaconCreate(player, gameA_artanisFirstArrivalTime);
}

void GameA_ArtanisHeroRevive (int player) {
    point spawnPoint;

    spawnPoint = GameA_ArtanisHeroSpawnPoint(player);
    UnitSetPosition(gameA_artanisHero[player], spawnPoint, false);
    UnitRevive(gameA_artanisHero[player]);
    UnitSetPropertyFixed(gameA_artanisHero[player], c_unitPropLifePercent, 100.0);
    UnitSetPropertyFixed(gameA_artanisHero[player], c_unitPropShieldsPercent, 100.0);
    GameA_ArtanisHeroRemoveAmonMechanics(gameA_artanisHero[player]);
    GameA_ArtanisBeaconRemove(player);
    libCOUI_gf_SetHeroPanelUnit(1, gameA_artanisHero[player], player);
    gameA_artanisHeroPhase[player] = 2;
    UIDisplayMessage(PlayerGroupSingle(player), c_messageAreaSubtitle, StringExternal("GameA/ArtanisHero/Arrival"));
}

bool GameA_ArtanisHeroTick (bool testConds, bool runActions) {
    int player;
    playergroup commanders;

    if (!runActions) {
        return true;
    }

    commanders = libCOOC_gf_CommanderPlayers();
    player = -1;
    while (true) {
        player = PlayerGroupNextPlayer(commanders, player);
        if (player < 0) {
            break;
        }

        if (!GameA_ArtanisHeroPlayerIsActive(player)) {
            continue;
        }
        if (gameA_artanisHeroPhase[player] == 0) {
            GameA_ArtanisHeroCreateWaiting(player);
        }
        else if ((gameA_artanisHeroPhase[player] == 1 || gameA_artanisHeroPhase[player] == 3) && PlayerGetCooldown(player, gameA_artanisHeroCooldown) <= 0.0) {
            GameA_ArtanisHeroRevive(player);
        }
    }
    return true;
}

bool GameA_ArtanisHeroDied (bool testConds, bool runActions) {
    int player;
    unit hero;

    hero = EventUnit();
    player = UnitGetOwner(hero);
    if (testConds && (player < 1 || player > 15 || hero != gameA_artanisHero[player] || !GameA_ArtanisHeroPlayerIsActive(player))) {
        return false;
    }
    if (!runActions) {
        return true;
    }

    // Phase 1 is the intentional hidden death used for the initial four-minute deployment.
    if (gameA_artanisHeroPhase[player] == 1) {
        return true;
    }

    gameA_artanisHeroPhase[player] = 3;
    GameA_ArtanisHeroStartCooldown(player, gameA_artanisReviveTime);
    GameA_ArtanisBeaconCreate(player, gameA_artanisReviveTime);
    UIDisplayMessage(PlayerGroupSingle(player), c_messageAreaSubtitle, StringExternal("GameA/ArtanisHero/Fallen"));
    return true;
}

void GameA_ArtanisHeroInit () {
    int player;

    UserDataSetString("PlayerCommanders", "ProtossArtanis", "HeroReviveLink", 1, gameA_artanisHeroCooldown);
    for (player = 0; player < 16; player += 1) {
        gameA_artanisHero[player] = null;
        gameA_artanisBeacon[player] = null;
        gameA_artanisHeroPhase[player] = 0;
    }

    gameA_artanisHeroTickTrigger = TriggerCreate("GameA_ArtanisHeroTick");
    TriggerAddEventTimePeriodic(gameA_artanisHeroTickTrigger, 1.0, c_timeGame);

    gameA_artanisHeroDiedTrigger = TriggerCreate("GameA_ArtanisHeroDied");
    TriggerAddEventUnitDied(gameA_artanisHeroDiedTrigger, null);
}
